from __future__ import annotations
import os, re, warnings
import numpy as np
from dpdata.abacus.stru import get_frame_from_stru
from dpdata.abacus.scf import bohr2ang, kbar2evperang3, get_geometry_in, get_mag_force

STEP_RE = re.compile(r"RELAX IONS\s*:\s*(\d+)\s*\(in total:\s*(\d+)\)")
STEP_RE2 = re.compile(r"RELAX IONS\s*:\s*(\d+)")
LATT_RE = re.compile(r"lattice constant \(Bohr\)\s*=\s*([-+]?[0-9]*\.?[0-9]+(?:[eE][-+]?[0-9]+)?)")

def _step_events(loglines):
    events=[]
    for i,line in enumerate(loglines):
        if "RELAX IONS" in line:
            m = STEP_RE.search(line)
            if m:
                step=int(m.group(2))
            else:
                m2 = STEP_RE2.search(line)
                if m2:
                    step=int(m2.group(1))
                else:
                    continue
            events.append((i,step))
    return events

def _step_for_line(line_idx, step_events):
    step=0
    for idx,num in step_events:
        if idx<=line_idx:
            step=num
        else:
            break
    return step

def _read_coords_at(loglines,i,natoms,coord_type,a0):
    coords=[]
    a0_ang=a0*bohr2ang
    for k in range(2,2+natoms):
        parts=loglines[i+k].split()
        vals=[float(x) for x in parts[1:4]]
        if coord_type=="CARTESIAN":
            vals=[v*a0_ang for v in vals]
        coords.append(vals)
    return np.array(coords), a0_ang

def _parse_log_structures(loglines, natoms, step_events):
    structures={}
    pending=None
    a0=None
    nblocks_step0=0
    for i,line in enumerate(loglines):
        m=LATT_RE.search(line)
        if m:
            a0=float(m.group(1)); continue
        toks=line.split()
        if len(toks)>=2 and toks[1]=="COORDINATES":
            ctype=toks[0]
            if ctype not in ("DIRECT","CARTESIAN"):
                raise RuntimeError(f"Unrecognized coordinate type {ctype} at line {i}")
            if a0 is None:
                raise RuntimeError(f"lattice constant not found before coordinate block at line {i}")
            step=_step_for_line(i,step_events)
            if step==0:
                idx=nblocks_step0
                nblocks_step0+=1
            else:
                idx=step
            coords,a0_ang=_read_coords_at(loglines,i,natoms,ctype,a0)
            if ctype=="DIRECT":
                # need cell later; store fractions and flag
                structures.setdefault(idx,{"coords":None,"cell":None,"direct":coords})
            else:
                structures.setdefault(idx,{"coords":coords,"cell":None,"direct":None})
            pending=idx
        elif line[1:56]=="Lattice vectors: (Cartesian coordinate: in unit of a_0)":
            if a0 is None:
                continue
            a0_ang=a0*bohr2ang
            cell=[]
            for k in range(1,4):
                cell.append([float(x)*a0_ang for x in loglines[i+k].split()[0:3]])
            cell=np.array(cell)
            step=_step_for_line(i,step_events)
            if pending is not None and structures.get(pending,{}).get("cell") is None:
                idx=pending
            elif step>0:
                idx=step
            else:
                # initial cell without coords
                idx=0
            structures.setdefault(idx,{"coords":None,"cell":None,"direct":None})
            structures[idx]["cell"]=cell
    # resolve direct coords
    for idx,st in structures.items():
        if st["direct"] is not None:
            if st["cell"] is not None:
                st["coords"]=st["direct"].dot(st["cell"])
            else:
                st["coords"]=st["direct"]  # fractions, no cell; won't be used
            st["direct"]=None
    return structures

def _parse_energy_records(loglines, step_events):
    recs=[]
    for i,line in enumerate(loglines):
        if line[1:14]=="final etot is" or "#TOTAL ENERGY#" in line:
            step=_step_for_line(i,step_events)
            val=float(line.split()[-2])
            recs.append((step,val))
    return recs

_FORCE_LINE = re.compile(r"^\s*[A-Z][a-z]?[1-9][0-9]*\s+[-+]?[0-9]*\.?[0-9]+([eE][-+]?[0-9]+)?\s+[-+]?[0-9]*\.?[0-9]+([eE][-+]?[0-9]+)?\s+[-+]?[0-9]*\.?[0-9]+([eE][-+]?[0-9]+)?\s*$")
_STRESS_LINE = re.compile(r"^\s*[-+]?[0-9]*\.?[0-9]+([eE][-+]?[0-9]+)?\s+[-+]?[0-9]*\.?[0-9]+([eE][-+]?[0-9]+)?\s+[-+]?[0-9]*\.?[0-9]+([eE][-+]?[0-9]+)?\s*$")

def _parse_force_records(loglines, step_events):
    recs=[]
    for i,line in enumerate(loglines):
        if "TOTAL-FORCE" in line:
            j=i
            found=False
            while j < len(loglines) and not _FORCE_LINE.match(loglines[j]):
                j+=1
                if j>=i+10:
                    warnings.warn("Warning: can not find the first line of force")
                    break
            block=[]
            while j < len(loglines) and _FORCE_LINE.match(loglines[j]):
                block.append([float(x) for x in loglines[j].split()[1:4]])
                j+=1
            if block:
                recs.append((_step_for_line(i,step_events), np.array(block)))
    return recs

def _parse_stress_records(loglines, step_events):
    recs=[]
    for i,line in enumerate(loglines):
        if "TOTAL-STRESS" in line:
            j=i
            while j < len(loglines) and not _STRESS_LINE.match(loglines[j]):
                j+=1
                if j>=i+10:
                    warnings.warn("Warning: can not find the first line of stress")
                    break
            block=[]
            while j < len(loglines) and _STRESS_LINE.match(loglines[j]):
                block.append([float(x) for x in loglines[j].split()[0:3]])
                j+=1
            if block:
                recs.append((_step_for_line(i,step_events), np.array(block)))
    return recs

def _snapshot_structures(output_dir, natoms):
    snaps={}
    if not os.path.isdir(output_dir):
        return snaps
    for fn in sorted(os.listdir(output_dir)):
        m=re.match(r"STRU_ION(\d+)_([DC])$", fn)
        if not m: continue
        step=int(m.group(1))
        try:
            data=get_frame_from_stru(os.path.join(output_dir,fn))
        except Exception as e:
            continue
        if sum(data["atom_numbs"])!=natoms:
            warnings.warn(f"snapshot {fn} has different atom number, skipped")
            continue
        snaps[step]={"coords":np.array(data["coords"][0]),"cell":np.array(data["cells"][0])}
    return snaps

def parse_trajectory(fname, loglines, data_initial):
    natoms=sum(data_initial["atom_numbs"])
    step_events=_step_events(loglines)
    log_struct=_parse_log_structures(loglines,natoms,step_events)
    energy_recs=_parse_energy_records(loglines,step_events)
    force_recs=_parse_force_records(loglines,step_events)
    stress_recs=_parse_stress_records(loglines,step_events)
    outdir=os.path.dirname(fname)
    snaps=_snapshot_structures(outdir,natoms)
    # merge
    structures={}
    for idx,st in log_struct.items():
        structures[idx]=dict(st)
    for step,st in snaps.items():
        structures.setdefault(step,{"coords":None,"cell":None})
        if structures[step]["coords"] is None:
            structures[step]["coords"]=st["coords"]
        if structures[step]["cell"] is None:
            structures[step]["cell"]=st["cell"]
    if 0 not in structures:
        structures[0]={"coords":None,"cell":None}
    if structures[0]["coords"] is None:
        structures[0]["coords"]=np.array(data_initial["coords"][0])
    if structures[0]["cell"] is None:
        structures[0]["cell"]=np.array(data_initial["cells"][0])
    # assign steps if no headers
    has_headers=len(step_events)>0
    if not has_headers:
        energy_recs=[(i+1,v) for i,(_,v) in enumerate(energy_recs)]
        force_recs=[(i+1,b) for i,(_,b) in enumerate(force_recs)]
        stress_recs=[(i+1,b) for i,(_,b) in enumerate(stress_recs)]
    energy_by_step={s:v for s,v in energy_recs}
    force_by_step={s:b for s,b in force_recs}
    stress_by_step={s:b for s,b in stress_recs}
    energies=[]; coords=[]; cells=[]; forces=[]; stresses=[]
    steps=[]
    for step in sorted(energy_by_step):
        st=structures.get(step-1)
        if st is None or st["coords"] is None or st["cell"] is None:
            print('skip missing structure for step',step)
            continue
        energies.append(energy_by_step[step])
        coords.append(st["coords"]); cells.append(st["cell"])
        forces.append(force_by_step.get(step))
        stresses.append(stress_by_step.get(step))
        steps.append(step)
    return dict(step_events=step_events, log_struct=log_struct, snaps=snaps, structures=structures,
                energy_recs=energy_recs, force_recs=force_recs, stress_recs=stress_recs,
                steps=steps, energies=energies, coords=coords, cells=cells, forces=forces, stresses=stresses)

if __name__=="__main__":
    import sys
    sys.path.insert(0,'/workspace/task/source')
    from dpdata.abacus.stru import get_frame_from_stru as gfs
    for name in ['abacus_relax_case','abacus_relax_normal','abacus_relax_abnormal','abacus_relax_nostress']:
        base=f'/workspace/task/fixtures/{name}'
        suff='ABACUS' if name=='abacus_relax_case' else 'abacus'
        logp=f'{base}/OUT.{suff}/running_cell-relax.log'
        with open(logp) as f: lines=f.read().split('\n')
        init=gfs(f'{base}/STRU')
        r=parse_trajectory(logp, lines, init)
        print('====',name,'headers',len(r['step_events']))
        print(' log_struct idx', sorted(r['log_struct']))
        print(' snaps idx', sorted(r['snaps']))
        print(' structures idx', sorted(r['structures']))
        print(' energy steps', [s for s,_ in r['energy_recs']])
        print(' force steps', [s for s,_ in r['force_recs']])
        print(' stress steps', [s for s,_ in r['stress_recs']])
        print(' frame steps', r['steps'])
        print(' energies', r['energies'])
        print(' coords0', np.array(r['coords'])[0][0] if r['coords'] else None)
        print(' coords-last', np.array(r['coords'])[-1][0] if r['coords'] else None)
        print(' cells0', np.array(r['cells'])[0] if r['cells'] else None)
        print(' cells-last', np.array(r['cells'])[-1] if r['cells'] else None)
        print(' force shapes', [None if f is None else f.shape for f in r['forces']])
        print(' stress shapes', [None if s is None else s.shape for s in r['stresses']])
