_RELAX_IONS_TOTAL_RE = re.compile(r"RELAX IONS\s*:\s*\d+\s*\(in total:\s*(\d+)\)")
_RELAX_IONS_RE = re.compile(r"RELAX IONS\s*:\s*(\d+)")
_LATTICE_CONSTANT_RE = re.compile(
    r"lattice constant\s*\(Bohr\)\s*=\s*([-+]?\d*\.?\d+(?:[eE][-+]?\d+)?)"
)
_STRU_ION_RE = re.compile(r"STRU_ION(\d+)_([DC])$")
_FORCE_LINE_RE = re.compile(
    r"^\s*[A-Z][a-z]?[1-9][0-9]*\s+[-+]?[0-9]*\.?[0-9]+([eE][-+]?[0-9]+)?\s+[-+]?[0-9]*\.?[0-9]+([eE][-+]?[0-9]+)?\s+[-+]?[0-9]*\.?[0-9]+([eE][-+]?[0-9]+)?\s*$"
)
_STRESS_LINE_RE = re.compile(
    r"^\s*[-+]?[0-9]*\.?[0-9]+([eE][-+]?[0-9]+)?\s+[-+]?[0-9]*\.?[0-9]+([eE][-+]?[0-9]+)?\s+[-+]?[0-9]*\.?[0-9]+([eE][-+]?[0-9]+)?\s*$"
)


def _get_step_events(loglines):
    """Collect the overall ion-step number printed for each RELAX IONS block.

    ABACUS prints lines such as ``RELAX IONS : 1 (in total: 2)``.  The
    number in parentheses is the overall ion-step index; when it is not
    present, the first number is used instead.
    """
    events = []
    for i, line in enumerate(loglines):
        if "RELAX IONS" not in line:
            continue
        match = _RELAX_IONS_TOTAL_RE.search(line)
        if match is not None:
            step = int(match.group(1))
        else:
            match = _RELAX_IONS_RE.search(line)
            if match is None:
                continue
            step = int(match.group(1))
        events.append((i, step))
    return events


def _get_step_number(line_idx, step_events):
    """Return the most recent ion-step number at or before ``line_idx``."""
    step = 0
    for idx, num in step_events:
        if idx <= line_idx:
            step = num
        else:
            break
    return step


def _read_log_coords(loglines, i, natoms, coord_type, a0):
    """Read one coordinate block from the relaxation log.

    Coordinates are returned in Angstrom.  Direct coordinates are returned
    as fractional coordinates and are converted later, when the cell is
    known.
    """
    coords = []
    for k in range(2, 2 + natoms):
        values = [float(x) for x in loglines[i + k].split()[1:4]]
        if coord_type == "CARTESIAN":
            values = [v * a0 * bohr2ang for v in values]
        coords.append(values)
    return np.array(coords)


def _parse_log_structures(loglines, natoms, step_events):
    """Extract structure blocks from the relaxation log.

    Each block is stored under the index of the ion step whose starting
    structure it describes: ``0`` is the initial structure and ``k >= 1``
    is the structure obtained after ion step ``k``.
    """
    structures = {}
    pending = None
    a0 = None
    nblocks_step0 = 0
    for i, line in enumerate(loglines):
        match = _LATTICE_CONSTANT_RE.search(line)
        if match is not None:
            a0 = float(match.group(1))
            continue
        tokens = line.split()
        if len(tokens) >= 2 and tokens[1] == "COORDINATES":
            coord_type = tokens[0]
            if coord_type not in ("DIRECT", "CARTESIAN"):
                raise RuntimeError(
                    f"Unrecognized coordinate type {coord_type} at line {i}"
                )
            if a0 is None:
                raise RuntimeError(
                    f"lattice constant not found before coordinate block at line {i}"
                )
            step = _get_step_number(i, step_events)
            if step == 0:
                idx = nblocks_step0
                nblocks_step0 += 1
            else:
                idx = step
            coords = _read_log_coords(loglines, i, natoms, coord_type, a0)
            struct = structures.setdefault(
                idx, {"coords": None, "cell": None, "direct": None}
            )
            if coord_type == "DIRECT":
                struct["direct"] = coords
            else:
                struct["coords"] = coords
            pending = idx
        elif line[1:56] == "Lattice vectors: (Cartesian coordinate: in unit of a_0)":
            if a0 is None:
                continue
            a0_ang = a0 * bohr2ang
            cell = np.array(
                [
                    [float(x) * a0_ang for x in loglines[i + k].split()[0:3]]
                    for k in range(1, 4)
                ]
            )
            step = _get_step_number(i, step_events)
            if pending is not None and structures.get(pending, {}).get("cell") is None:
                idx = pending
            elif step > 0:
                idx = step
            else:
                idx = 0
            struct = structures.setdefault(
                idx, {"coords": None, "cell": None, "direct": None}
            )
            struct["cell"] = cell
    return structures


def _parse_snapshot_structures(outdir, natoms):
    """Read per-step STRU_ION snapshots from the ABACUS output directory."""
    snapshots = {}
    if not os.path.isdir(outdir):
        return snapshots
    for name in sorted(os.listdir(outdir)):
        match = _STRU_ION_RE.match(name)
        if match is None:
            continue
        step = int(match.group(1))
        path = os.path.join(outdir, name)
        try:
            data = get_frame_from_stru(path)
        except Exception:
            continue
        if sum(data["atom_numbs"]) != natoms:
            warnings.warn(
                f"ABACUS relaxation snapshot {name} has a different atom number "
                "and is skipped.",
                UserWarning,
            )
            continue
        snapshots[step] = {
            "coords": np.array(data["coords"][0]),
            "cell": np.array(data["cells"][0]),
        }
    return snapshots


def _parse_energy_records(loglines, step_events):
    records = []
    for i, line in enumerate(loglines):
        if line[1:14] == "final etot is" or "#TOTAL ENERGY#" in line:
            step = _get_step_number(i, step_events)
            value = float(line.split()[-2])
            records.append((step, value))
    return records


def _parse_force_records(loglines, step_events):
    records = []
    for i, line in enumerate(loglines):
        if "TOTAL-FORCE" not in line:
            continue
        j = i
        while j < len(loglines) and _FORCE_LINE_RE.match(loglines[j]) is None:
            j += 1
            if j >= i + 10:
                warnings.warn("Warning: can not find the first line of force")
                break
        block = []
        while j < len(loglines) and _FORCE_LINE_RE.match(loglines[j]) is not None:
            block.append([float(x) for x in loglines[j].split()[1:4]])
            j += 1
        if block:
            records.append((_get_step_number(i, step_events), np.array(block)))
    return records


def _parse_stress_records(loglines, step_events):
    records = []
    for i, line in enumerate(loglines):
        if "TOTAL-STRESS" not in line:
            continue
        j = i
        while j < len(loglines) and _STRESS_LINE_RE.match(loglines[j]) is None:
            j += 1
            if j >= i + 10:
                warnings.warn("Warning: can not find the first line of stress")
                break
        block = []
        while j < len(loglines) and _STRESS_LINE_RE.match(loglines[j]) is not None:
            block.append([float(x) for x in loglines[j].split()[0:3]])
            j += 1
        if block:
            records.append((_get_step_number(i, step_events), np.array(block)))
    return records


def _parse_mag_records(loglines, step_events):
    magmom_records = []
    magforce_records = []
    for i, line in enumerate(loglines):
        if "Total Magnetism (uB)" in line:
            j = i + 2
            mag = []
            while j < len(loglines) and "-------------------------" not in loglines[j]:
                values = [float(x) for x in loglines[j].split()[1:]]
                if len(values) == 1:
                    values = [0, 0, values[0]]
                mag.append(values)
                j += 1
            if mag:
                magmom_records.append((_get_step_number(i, step_events), np.array(mag)))
        if "Magnetic force (eV/uB)" in line:
            j = i + 2
            mag = []
            while j < len(loglines) and "-------------------------" not in loglines[j]:
                values = [float(x) for x in loglines[j].split()[1:]]
                if len(values) == 1:
                    values = [0, 0, values[0]]
                mag.append(values)
                j += 1
            if mag:
                magforce_records.append(
                    (_get_step_number(i, step_events), np.array(mag))
                )
    return magmom_records, magforce_records


def _records_to_dict(records):
    result = {}
    for step, value in records:
        result[step] = value
    return result


def _merge_structures(log_structures, snapshots, initial):
    """Merge structures read from the log and from STRU_ION snapshots."""
    structures = {}
    for idx, struct in log_structures.items():
        structures[idx] = dict(struct)
    # The STRU_ION files are written with full precision, so they take
    # precedence over the (possibly rounded) values printed in the log.
    for step, struct in snapshots.items():
        structures.setdefault(step, {"coords": None, "cell": None, "direct": None})
        structures[step]["coords"] = struct["coords"]
        structures[step]["cell"] = struct["cell"]
        structures[step]["direct"] = None

    structures.setdefault(0, {"coords": None, "cell": None, "direct": None})
    if structures[0]["coords"] is None and structures[0].get("direct") is None:
        structures[0]["coords"] = np.array(initial["coords"][0])
    if structures[0]["cell"] is None:
        structures[0]["cell"] = np.array(initial["cells"][0])

    # A fixed-cell relaxation does not print a new cell after each ion step.
    for idx in sorted(structures):
        if structures[idx]["cell"] is None and idx > 0:
            prev = structures.get(idx - 1)
            if prev is not None and prev["cell"] is not None:
                structures[idx]["cell"] = prev["cell"]

    for struct in structures.values():
        if struct.get("direct") is not None:
            if struct["cell"] is not None:
                struct["coords"] = struct["direct"].dot(struct["cell"])
            else:
                struct["coords"] = struct["direct"]
            struct["direct"] = None
    return structures


def _parse_relax_trajectory(loglines, natoms, initial, outdir):
    """Rebuild a relaxation trajectory from the log and STRU_ION snapshots.

    Energies, forces and stresses are aligned to the ion step that produced
    them, and each frame uses the structure on which that ion step was
    performed.  When the log does not print a structure after an ion step,
    the corresponding STRU_ION snapshot is used instead.
    """
    step_events = _get_step_events(loglines)
    has_headers = len(step_events) > 0
    log_structures = _parse_log_structures(loglines, natoms, step_events)
    snapshots = _parse_snapshot_structures(outdir, natoms)
    structures = _merge_structures(log_structures, snapshots, initial)

    energy_records = _parse_energy_records(loglines, step_events)
    force_records = _parse_force_records(loglines, step_events)
    stress_records = _parse_stress_records(loglines, step_events)
    magmom_records, magforce_records = _parse_mag_records(loglines, step_events)

    # Older ABACUS logs do not print RELAX IONS markers.  Their records are
    # already ordered by ion step, so assign the step numbers sequentially.
    if not has_headers:
        energy_records = [(i + 1, v) for i, (_, v) in enumerate(energy_records)]
        force_records = [(i + 1, v) for i, (_, v) in enumerate(force_records)]
        stress_records = [(i + 1, v) for i, (_, v) in enumerate(stress_records)]
        magmom_records = [(i + 1, v) for i, (_, v) in enumerate(magmom_records)]
        magforce_records = [(i + 1, v) for i, (_, v) in enumerate(magforce_records)]

    energy_by_step = _records_to_dict(energy_records)

    steps = []
    energies = []
    coords = []
    cells = []
    for step in sorted(energy_by_step):
        struct = structures.get(step - 1)
        if struct is None or struct["coords"] is None or struct["cell"] is None:
            continue
        steps.append(step)
        energies.append(energy_by_step[step])
        coords.append(struct["coords"])
        cells.append(struct["cell"])

    return {
        "steps": steps,
        "energies": np.array(energies),
        "coords": np.array(coords),
        "cells": np.array(cells),
        "force_by_step": _records_to_dict(force_records),
        "stress_by_step": _records_to_dict(stress_records),
        "magmom_by_step": _records_to_dict(magmom_records),
        "magforce_by_step": _records_to_dict(magforce_records),
    }


